Our basic problem of interest in this paper is the quasi-variational inequality (QVI) problem to find $y\in K(x, y)$, for a given parameter $x\in \mathbb{R}^n$, such that we have 
\begin{equation}\tag{QVI}\label{VI}
\left\langle f_0(x,y), \;\, \varsigma - y \right\rangle \geq 0 \;\;\;
 \forall \varsigma\in  K(x, y):= \left\{\varsigma \in \mathbb{R}^m\left|\; g_0(x, y, \varsigma)\leq 0\right.\right\},
\end{equation}

where $f_0 : \mathbb{R}^n\times \mathbb{R}^m \rightarrow \mathbb{R}^m$ is a continuously differentiable function
and $K :\mathbb{R}^n\times \mathbb{R}^m \rightrightarrows \mathbb{R}^m$ denotes the feasibility
set-valued map defined by a function $g_0\, : \mathbb{R}^n\times \mathbb{R}^m\times \mathbb{R}^m \rightarrow \mathbb{R}^q$,
 which is also assumed to be continuously differentiable.


\begin{equation}\label{S-Soultion-Map}
\begin{array}{c}
  S(x):=\left\{y\in K(x,y)\left|\; \left\langle f_0(x,y), \;\, \varsigma - y \right\rangle \geq 0  \;\;\; \forall \varsigma\in K(x, y)\right.\right\}
\end{array}
\end{equation}

\begin{equation}\label{VI-1}
 S(x):=\left\{y\in K(x,y)\left|\;\, y^\top f_0(x,y)-\varphi(x,y)\leq 0\right.\right\}
%    y\in K(x, y) \mbox{ such that } f(x,y,y)-\varphi(x,y)\leq 0.
\end{equation}

for all $x\in \mathbb{R}^n$. Here, $\varphi$ denotes the optimal value function
\begin{equation}\label{varphi}
   \varphi(x,y):= \underset{\varsigma}\min \{\varsigma^\top f_0(x, y)|\;\; \varsigma\in K(x, y)\}.
\end{equation}

For the points $(\bar x, \bar y)$, $(\bar x, \bar y, \bar y)$, and $(\bar x, \bar y, \bar\varsigma)$, the following notation will be used to collect { {active index sets}} of constraints for the feasible sets associated to problems \eqref{VI} and \eqref{OPQVIC}, which are defined by the functions $(x, y) \mapsto G(x, y)$, $(x, y) \mapsto g_0(x, y, y)$, and $(x, y, \varsigma) \mapsto g_0(x, y, \varsigma)$, respectively:
\begin{equation}\label{I1}
\begin{array}{lclll}
     I^1&:=& I^G(\bar x, \bar y)                   &:=&  \left\{i\in \{1, \ldots, p\}\left|~G_i(\bar x, \bar y)=0\right.\right\},\\[1ex]
    I^2 &:=& I^{g_0}(\bar x, \bar y, \bar y)       &:=& \left\{j\in \{1, \ldots, q\}|~g_{0_j}(\bar x, \bar y, \bar y)=0\right\},\\[1ex]
    I^3 &:=& I^{g_0}(\bar x, \bar y, \bar\varsigma)&:=& \left\{j\in \{1, \ldots, q\}|~g_{0_j}(\bar x, \bar y, \bar\varsigma)=0\right\}.
\end{array}
\end{equation}

{ {Although symbols that we use here are very standard, it might be useful to make it clear how we use the symbol $\nabla$ interchangeably between the gradient of a scalar function and the Jacobian of a vector-valued function. For a continuously differentiable function $\psi : \mathbb{R}^n\times \mathbb{R}^m \times \mathbb{R}^p \rightarrow \mathbb{R}^q$, in case there is ambiguity in the use of the usual partial derivatives, we will utilize $\nabla_1 \psi(x, y, \varsigma)$, (resp. $\nabla_2 \psi(x, y, \varsigma)$, $\nabla_3 \psi(x, y, \varsigma)$) to represent the Jacobian of the function $x \mapsto \psi(x, y, \varsigma)$ (resp. $y \mapsto \psi(x, y, \varsigma)$, $\varsigma \mapsto \psi(x, y, \varsigma)$) when the vector $(y, \varsigma)$ (resp. $(x, \varsigma)$, $(y, \varsigma)$) is fixed. A similar notation will be used for the gradient of $\psi$ if it is a real-valued function. Common scenarios for $\psi$ in this paper will be $\psi(x, y, \varsigma):= g_0(x, y, \varsigma)$ and $\psi(x, y, \varsigma):= \varsigma^\top f_0(x, y)$ when studying our \eqref{VI}.


Given that the optimal value function $\varphi$ \eqref{varphi} is nonsmooth in general, we need generalized concepts of
 differentiability to deal with it. We start the discussion on this by recalling the \emph{generalized directional derivative} in the sense of
 Clarke \cite{ClarkeBook1983}, which, for a function $\psi : \mathbb{R}^n \rightarrow \mathbb{R}$, is defined at a point $\bar{x}\in \mathbb{R}^n$ in direction $d\in \mathbb{R}^n$ by
 \begin{equation*}\label{Clarke Directional Derivative}
    \psi^0(\bar x; d):=\underset{t\downarrow 0}{\underset{x \rightarrow \bar x}\limsup} \frac{1}{t}\left[\psi(x + td)-\psi(x)\right].
\end{equation*}
 This quantity exists if $\psi$ is a Lipschitz continuous function around $\bar x$ \cite[Proposition 2.1.1]{ClarkeBook1983}.
  Utilizing this notion, the \textit{Clarke subdifferential} of $\psi$ at the point $\bar{x}$ can be defined by 
\begin{equation}\label{Clarke Subdifferential}
    \bar\partial \psi(\bar x):= \left\{\zeta\in \mathbb{R}^n|\; \psi^o(\bar x; d)\geq \langle\zeta, d\rangle, \; \forall d\in \mathbb{R}^n  \right\}.
\end{equation}
Note that {{$\bar\partial \psi(\bar x) = \left\{\nabla \psi(\bar x)\right\}$ }} if $\psi$ is continuously differentiable at $\bar x$, and for a convex function,
this concept coincides with the subdifferential in the sense of convex analysis.
Furthermore, this concept can be extended to a vector-valued function $\psi : \mathbb{R}^n \rightarrow \mathbb{R}^m$ that
is Lipschitz continuous around a point $\bar x$, as such a function is differentiable almost everywhere around this point. Hence,
 the \emph{Clarke generalized Jacobian} of the function $\psi$ at the point $\bar{x}$ can be written as 
\begin{equation}\label{Clarke Subdifferential-Derivative}
    \bar\partial \psi(\bar x):= \mbox{co}\left\{\lim\nabla\psi(x^n)\left|~x^n \rightarrow \bar x, \;\, x^n\in D_\psi \right.\right\},
\end{equation}
where ``co'' stands for the convex hull and  $D_\psi$ represents the set of points where $\psi : \mathbb{R}^n \rightarrow \mathbb{R}^m$ is
differentiable. { {Note that the quantity defined in  \eqref{Clarke Subdifferential-Derivative} coincides with the one in \eqref{Clarke Subdifferential}
 for real-valued functions}}. Following  the expression in \eqref{Clarke Subdifferential-Derivative},


{ {In the sequel, the concept of basic normal cone will also be necessary. 
 For a closed subset $C$ of $\mathbb{R}^n$, the \textit{basic} (also known as \emph{Mordukhovich} or \textit{limiting}) \textit{normal cone}
 to $C$ at one of its points $\bar x$ is the set
\begin{equation}\label{basic normal cone}
 N_C(\bar x):= \left\{v\in \mathbb{R}^n\left|\; \exists v_k \rightarrow v, \, x_k \rightarrow \bar x \,(x_k\in C): \, v_k\in \widehat{N}_C(x_k)\right.\right\},
\end{equation}
where $\widehat{N}_C$ denotes the polar of the contingent/Boulingand tangent cone to $C$}}:
\begin{equation}\label{polar normal cone}
 \widehat{N}_C(\bar x):=\left\{v\in \mathbb{R}^n \left |\; \langle v, u-\bar x\rangle \leq o(\|u-\bar x\|)\;\; \forall u\in C\right. \right\}.
\end{equation}
$\widehat{N}_C(\bar{x})$ is also known as the \textit{regular} or \textit{Fr\'{e}chet} normal cone. A set $C \subset \mathbb{R}^n$ is said to be \textit{normally regular} at $\bar{x} \in C$ if $ N_C(\bar{x}) = \widehat{N}_C(\bar{x})$. If $C$ is a convex set, it is normally regular at all points of $C$, given that both of the above cones coincide with the normal cone in the sense of convex analysis.

The regular normal cone allows us to introduce the notion of a \textit{regular subdifferential} also known as the Fr\'{e}chet subdifferential. Let the function $\psi : \mathbb{R}^n \rightarrow \mathbb{R}$ be Lipschitz continuous around $\bar x$. Then its regular subdifferential at $\bar{x} \in \mathbb{R}^n$ is given as 
\[
    \hat{\partial}\psi(\bar{x}) = \left\{v\in \mathbb{R}^n\left|~(v, -1) \in \widehat{N}_{\mbox{epi}\psi} (\bar{x}, \psi(\bar{x}))\right.\right\},
\]
where epi$\psi$ denotes the epigraph of the function $\psi$.
Let us now introduce the notion of a \textit{basic subdifferential} which is also known as the \textit{limiting} subdifferential or the \textit{Mordukhovich} subdifferential. For $\psi : \mathbb{R}^n \rightarrow \mathbb{R}$, which Lipschitz continous around $\bar x$, its basic subdifferential at this point is given by 
\[
    \partial\psi(\bar{x}) = \left\{v\in \mathbb{R}^n\left|~(v, -1) \in N_{\mbox{epi}\psi} (\bar{x}, \psi(\bar{x}))\right.\right\}.
\]
Considering the interplay between \eqref{basic normal cone} and \eqref{polar normal cone}, $v \in \partial \psi(\bar{x})$ if and only if there exist sequences $\{x^k \}$ with $x^k \rightarrow \bar{x}$ and $\{v^k\}$ with $ v^k \rightarrow v$ such that $v^k \in \hat{\partial} \psi(x^k)$. The basic subdifferential for a locally Lipschitz function is always non-empty and compact. If $\psi$ is a convex function, then both its regular and basic subdifferentials coincides with the subdifferential in the sense of convex analysis. Furthermore, if a function $\psi : \mathbb{R}^n \rightarrow \mathbb{R}$ is Lipschitz continous around a point $\bar x$, then we have the nice relationship
\begin{equation}\label{LimitingClarke}
    \bar{\partial}\psi = \mbox{cl} \mbox{co}\partial \psi (\bar{x})
\end{equation}
between the Clarke and basic subdifferentials; cf. \cite[Theorem 3.57 of Volume I]{MordukhovichBook2006}, where $\mbox{cl} \mbox{co}$ stands for the closure of the convex hull of the corresponding set. Hence, the Clarke subdifferential is often referred to in some literature as the \textit{convexified subdifferential}.


Set-valued mappings and some related concepts will play a key role in the derivation of key results in this paper. To proceed, we consider a set-valued mapping $\Psi :\mathbb{R}^n\rightrightarrows\mathbb{R}^m$. 
{ {The domain of $\Psi$ is denoted as $\text{dom}\Psi$ and defined by
$\text{dom}\Psi := \{ x \in \mathbb{R}^n  \left| \ \Psi(x) \neq \emptyset\right\}$,
while its graph, denoted as $\text{gph} \Psi$, is given by
\begin{equation*}
    \text{gph} \Psi  :=  \{ (x, y) \in \mathbb{R}^m \times \mathbb{R}^m \left | \ y \in \Psi(x) \right \} = \{ (x, y) \in \text{dom} \Psi \times \mathbb{R}^m \left|\ y \in \Psi(x)\right\}.
\end{equation*}
}} 


 { {The set-valued mapping $\Psi :\mathbb{R}^n\rightrightarrows\mathbb{R}^m$ is said to be 
 { {inner semicontinuous at $(\bar{x},\bar{y})\in \mbox{gph}\Psi$ w.r.t. $\Omega\in\mathbb{R}^{n}$ whenever for each neighborhood $V\subset \mathbb{R}^{m}$ of $\bar{y}$, there exists a neighborhood $U\subset \mathbb{R}^{n}$ of $\bar{x}$ such that $\Psi (x)\cap V\neq \emptyset$ for all $x \in \Omega \cap U$. If $\Omega = \mathbb{R}^{n}$ can be chosen, $\Psi$ is called inner semicontinuous at $(\bar{x},\bar{y})$ for brevity; i.e., if for every sequence $x_k\rightarrow\bar{x}$, there is a sequence of $y_k\in\Psi(x_k)$ that converges to $\bar{y}$ as $k\rightarrow\infty$. For single-valued mappings $\Psi :\mathbb{R}^n\to\mathbb{R}^m$, this property obviously reduces to the continuity of $\Psi$ at $\bar x$.}} %Furthermore, if $\Psi :\mathbb{R}^n \rightrightarrows\mathbb{R}^m$ is inner semicompact at $\bar{x}$ with $\Psi(\bar{x})=\{\bar{y}\}$, then $\Psi$ is inner semicontinuous at $(\bar x, \bar y)$.
 Obviously, the inner semicontinuity property is more restrictive than the inner semicompactness while bringing us to more precise results of the coderivative calculus, as it will be clear in the next section.}} 


As it will become clear in the subsequent sections, some Lipschitz-type properties will also play a central role in the main results. Hence, we introduce some useful concepts.  A set-valued mapping $\Psi : \mathbb{R}^{n}\rightrightarrows \mathbb{R}^{m}$
is said to be \emph{Lipschitz-like} (or satisfies the \textit{Aubin property} \cite{Aubin1984}) around $\left(\bar{x},\bar{y}\right)\in \mbox{gph}\Psi$ if
 there exist neighborhoods $U$ of $\bar{x}$, $V$ of $\bar{y}$, and a constant $l > 0$ such that
\begin{equation}\label{exact-estim}
	\Psi\left( x\right) \cap V \subseteq \Psi\left( u\right) +l\|u-x\|\mathbb{B} \ \ \text{for all} \ x,u \in U
\end{equation}
with $\mathbb{B}$ denoting the unit ball in $\mathbb{R}^{m}$ (see; e.g., \cite{HenrionJouraniOutrataCalmness2002}). This property can be equivalently expressed as 
\begin{equation}\label{Aubin-Property}
    d(y, \Psi(u)) \le l \| x - u \| \,\mbox{ for all }\, x, u \in U \;\, \mbox{and}\;\, y \in V \cap\Psi(x).
\end{equation}
The weaker calmness property can be obtained from \eqref{Aubin-Property} by setting $ u = \bar{x}$. Thus, the set-valued mapping $\Psi :\mathbb{R}^n \rightrightarrows \mathbb{R}^m$ will be said to be \textit{calm} (or satisfy the {\em calmness} property) at the point $(\bar x, \bar y)$ with $\bar y\in \Psi(\bar x)$, if there exist neighborhoods $U$ and $V$ of $\bar x$ and $\bar y$, respectively, and a constant $\ell >0$ such that
\begin{equation}\label{Definition Calmness}
d(y, \Psi(\bar x))\leq \ell \|x-\bar x\| \,\mbox{ for all }\, y\in V\cap \Psi(x), \;\, x\in U.
\end{equation}


  As an important application of calmness, note that based on \cite[Theorem 4.1]{HenrionJouraniOutrataCalmness2002}, inclusion \eqref{normal cone to operator constraint} also holds if the following set-valued mapping is calm at the point $(0, \bar x)$ with $\bar x\in \Omega \cap \psi^{-1}(\Xi)$: 
\begin{equation}\label{CalmnesMapAgain}
\Psi(\varsigma):=\left\{x\in \Omega\left|\;\, \psi(x) + \varsigma \in \Xi\right.\right\}.
\end{equation}

  Next, we use the concept of basic normal cone introduced in the previous subsection to define the notion of {\em coderivative}, which will allow us to present the most powerful characterization of the Lipschitz-likeness property.  For a given set-valued mapping $\Psi :\mathbb{R}^n \rightrightarrows \mathbb{R}^m$,  its coderivative at some point $(\bar{x}, \bar{y})\in \text{gph}\, \Psi$ corresponds to another set-valued mapping 
$D^*\Psi(\bar{x},\bar{y}): \mathbb{R}^m \rightrightarrows \mathbb{R}^n$ that is defined at any $y^*\in \mathbb{R}^m$ by
\begin{equation*}\label{cod-definition}
   D^*\Psi(\bar{x},\bar{y})(y^*):= \left\{x^*\in \mathbb{R}^n|\; (x^*, -y^*)\in N_{\text{gph}\, \Psi}(\bar{x}, \bar{y})\right\}.
\end{equation*}
For a single-valued locally Lipschitz continuous function $\psi : \mathbb{R}^n \rightarrow \mathbb{R}^m$, the coderivative reduces to  
\begin{equation*}\label{coderivative-sub}
    D^* \psi (\bar{x}) (y^*) = \partial \langle y^*,  \psi \rangle (\bar{x}),
\end{equation*}
where similarly to \eqref{normal cone to operator constraint}, the term $\partial \langle y^*, \psi \rangle (\bar x)$ denotes the basic subdifferential of the function $x \mapsto \sum^m_{i=1} y^*_i \psi_i(x)$ at $\bar x$.
The coderivative plays a key role in identifying whether a set-valued mapping is Lipschitz-like; i.e., the well-known \textit{Murdokhovich} criterion (see, e.g., \cite{RockafellarWetsBook1998,MordukhovichGeneralizedDifferential1994}), which says that for a set-valued mapping $\Psi : \mathbb{R}^{n}\rightrightarrows \mathbb{R}^{m}$, which has a closed graph around $(\bar x, \bar y)\in \text{gph}\Psi$, it is Lipschitz-like around this point if and only if 
\begin{equation*} \label{Aubin}
    D^* \Psi ( \bar{x}, \bar{y})(0) = \{0\}.
\end{equation*}
Thanks to the concept of coderivative, we can also characterize the \textit{Lipschitz modulus} of a set-valued mapping when it is Lipschitz-like \eqref{exact-estim}. To present this characterization, we first introduce the notion a Lipschitz modulus of a set-valued mapping $\Psi : \mathbb{R}^{n}\rightrightarrows \mathbb{R}^{m}$. For this, we need  the notion of \textit{outer norm}  %and \textit{inner norm}  
of a positively homogeneous set-valued mapping. { {Note that $\Psi$ is said to be positively homogeneous if $0\in \Psi (0)$ and $\Psi (\lambda x) = \lambda \Psi (x) $ for all $\lambda > 0$ and $ x \in \mathbb{R}^n$.}}
If $\Psi$ is a positively homogeneous
mapping, its \emph{outer norm} is defined by
\begin{equation*}
	\|\Psi\|^{+} :={\displaystyle \sup_{x\in\mathbb{B}}} \
{\displaystyle \sup_{u\in\Psi\left( x\right) }}\|u\|.  %\ \ \ \left(\text{resp.} \
%\|\Psi\|^{-} :={\displaystyle \sup_{x\in\mathbb{B}}} \ {\displaystyle \inf_{u\in\Psi\left( x\right) }} \|u\|\right).
\end{equation*}
Furthermore, the infinimum of all $l > 0$ for which \eqref{exact-estim} holds, also known as the \emph{Lipschitz modulus} of $\Psi$ at $\left(\bar{x},\bar{y}\right)$, is given as follows (cf. \cite[Theorem 9.40]{RockafellarWetsBook1998}),  via the outer norm of the coderivative of the set-valued mapping $\Psi$:
\begin{equation}\label{LipModulus}
	\text{lip} \Psi \left( \bar{x},\bar{y}\right) := \inf \left\{l\in ]0, +\infty[ \ |
\eqref{exact-estim} \ \text{holds for some} \  U \ \text{and} \ V  \right\}=\left\|D^{\ast}\Psi\left( \bar{x},\bar{y}\right)\right\|^{+}.
\end{equation}


The plan here is to use the value function reformulation \eqref{VI-1} of  $S$ \eqref{S-Soultion-Map} to construct an estimate for its coderivative  in terms of the derivatives of $f_0$ and $g_0$, and subsequently, to leverage on this result to provide new rules for the Lipschitz-like property of this set-valued mapping. To proceed,  some further definitions and notations are in order. First, the Mangasarian-Fromowitz constraint qualification (MFCQ) for the constraint describing $K$ \eqref{VI},  which will be said to hold at $(\bar x, \bar y, \bar\varsigma)$ if there exists a vector $d\in \mathbb{R}^m$ such that
\begin{equation}\label{LL regularity}
    \nabla_3 g_{0j}(\bar x, \bar y, \bar\varsigma)^\top d < 0\;  
    \mbox{ for all }\; j\in I^3.  %:= I^3(\bar x, \bar y, \bar\varsigma):= \left\{i|\; g_{0_{i}}(\bar x, \bar y, \bar\varsigma)=0\right\}
\end{equation}

Recall that $I^3$ is defined in \eqref{I1} and $\nabla_3 g_{0j}(x, y, \varsigma)$ represents the Jacobian of the function $\varsigma \mapsto g_{0j}(x, y, \varsigma)$ for a fixed vector $(x, y)\in \mathbb{R}^n\times \mathbb{R}^m$.
Next, we associate to a vector $(\bar x, \bar y, \bar\varsigma, \varsigma^*)$ a set of  Lagrange multipliers
\begin{equation*}
  \Lambda^{0}(\bar x, \bar y, \bar\varsigma, \varsigma^*)
   :=  \left\{\left(\begin{array}{c}
        v\\ w\\ \lambda
\end{array}\right)\in \mathbb{R}^{2q + 1} \left|
\left.\begin{array}{l}
   \lambda \geq 0,\; v\geq 0, \; g_0(\bar x, \bar y, \bar{y})\leq 0, \; v^\top g_0(\bar x, \bar y, \bar{y})=0,\;  w\in \Lambda(\bar x, \bar y, \bar \varsigma)\\[1ex]
     \varsigma^*  + \lambda\left.\left(f_0(\bar x, \bar y) + \nabla_2f_0(\bar x, \bar y)^\top (\bar y - \bar\varsigma) - \nabla_2 g_{0}(\bar x, \bar y, \bar\varsigma)^{\top}w  \right)\right.\\[1ex]
      \qquad \qquad \qquad \qquad    \qquad \qquad \qquad \qquad + \nabla_2 g_{0}(\bar x, \bar y, \bar y)^{\top}v=0
      \end{array}\right.\right.\right\} 
\end{equation*}

related to the  problem  \eqref{VI}, with $\nabla_2 f_{0}(x, y)$ denoting the Jacobian of the function $f_{0}(x, .)$ for a fixed vector $x\in \mathbb{R}^n$, while $\nabla_2 g_{0}(x, y, \varsigma)$ represents the Jacobian of the function $g_{0}(x, ., \varsigma)$ with $(x, \varsigma)\in \mathbb{R}^n\times \mathbb{R}^m$ fixed. Furthermore, recall that the other involved set of Lagrange multipliers %$\Lambda(\bar x, \bar y, \hat{y})$ is defined by
\begin{equation}\label{Lambda(x,y)}
\begin{array}{rll}
\Lambda(x, y, \varsigma) &:=& \left\{w\in \mathbb{R}^q\left|\;\nabla_3\ell(x, y, \varsigma, w)=0,\right.\right.\left. \left. w\geq 0, \; g_0(x, y, \varsigma)\leq 0,\; w^{\top}g_0(x, y, \varsigma)= 0 \right.\right\}
\end{array}
\end{equation}

is defined with $x\in \mathbb{R}^n$ and $(y,\varsigma)\in \mathbb{R}^{2m}$. In \eqref{Lambda(x,y)}, the function $\ell$ represents the Lagrangian function associated with the underlying parametric optimization problem \eqref{varphi}:


\begin{equation}\label{ell}
    \ell(x, y, \varsigma, w):=\varsigma^\top f_0(x, y)+ w^\top g_0(x, y, \varsigma).
 \end{equation}

Furthermore, in \eqref{Lambda(x,y)},  $\nabla_3 \ell(x, y, \varsigma, w) := f_0(x, y) + \nabla_3 g_{0}(x, y, \varsigma)^\top w$ with $\nabla_3 g_{0}(x, y, \varsigma)$ denoting the Jacobian of the function $\varsigma \mapsto g_{0j}(x, y, \varsigma)$
when the vectors $x\in \mathbb{R}^n$ and $y\in \mathbb{R}^m$ are fixed.


$S(x)=\left\{y\in \mathbb{R}^m|\, y\in S_0(x, y)\right\}$,
where  $S_0 : \mathbb{R}^n\times \mathbb{R}^m \rightrightarrows \mathbb{R}^m$ is given as
\begin{equation}\label{S-v}
 S_0(x,y)  := \arg\underset{\varsigma}\min~\left\{\varsigma^\top f_0(x,y)\left|\; \varsigma\in K(x, y)\right.\right\}.
\end{equation}

with the notation $z:=(x, y)$, $g(x,y):= g_0(x, y, y)$, and $f(x,y) := y^\top f_0  (x,y)$, %introduced in Section \ref{Basic concepts and background material}
as well as the optimal value function $\varphi$ defined in \eqref{varphi}.

