\begin{lemma}[see Theorem 6.10 in \cite{MordukhovichGeneralizedDifferential1994} or Theorem 6.14 in  \cite{RockafellarWetsBook1998}]\label{normal cone estimate}
Let $C:=\Omega \cap \psi^{-1}(\Xi)$, where $\Omega \subseteq \mathbb{R}^n$ and $\Xi\subseteq \mathbb{R}^m$
are closed sets and the function $\psi :\mathbb{R}^n \rightarrow \mathbb{R}^m$ is  Lipschitz  around $\bar{x}$. Furthermore, assume that %Assume that the following qualification condition holds at $\bar{x} \in C $: whenever $v\in   N_{\varsigma}(\psi(\bar{x}))$, be such that
\begin{equation}\label{BCQ}
\left.
\begin{array}{r}
   0\in  \partial \langle v, \psi \rangle (\bar{x})+N_{\Omega}(\bar x)\\
   v\in   N_{\Xi}(\psi(\bar{x}))
\end{array}
\right\} \Longrightarrow v=0.    
\end{equation}
%{ {(The limiting subdiffential does not seem to have been introduced yet; this should be done and link to Clarke subdifferential discussed. This is needed in the proof of Theorem 3.1.)}}
Then the following estimate holds:
\begin{equation}\label{normal cone to operator constraint}
   N_C(\bar x) \subseteq     \bigcup\left\{\partial \langle v, \psi \rangle (\bar x) + N_{\Omega}(\bar x)\left|\; v\in N_\Xi(\psi(\bar x)) \right.\right\}.
\end{equation}
Equality holds in \eqref{normal cone to operator constraint}, provided that $\Xi$ is normally regular at $\psi(\bar x) $ and $ \Omega$ is normally regular at $\bar{x}$.
\end{lemma}

\begin{proof}
To begin, note that with the expression of the set-valued mapping $S$ \eqref{VI-1}, we have  
\[
\begin{array}{l}
\mbox{gph}S = \Omega \cap \psi^{-1}(\mathbb{R}_-)\,
\mbox{ with } \, \Omega:=\left\{(x, y)\in \mathbb{R}^n\times \mathbb{R}^m\left|\, \tilde{g}(x, y)\leq 0 \right.\right\},\, \psi(x, y):= \tilde{f}(x, y) - \varphi(x, y),
\end{array}
\]
where $\tilde{g}(x,y):= g_0(x, y, y)$ and $\tilde{f}(x, y):=y^\top f_0(x, y)$. Then observe that the function $\varphi$ is Lipshitz continuous around  $(\bar x, \bar y)$ given that the set-valued mapping $S_0$ \eqref{S-v} is inner semicontinuous at $(\bar x, \bar y, \bar{\varsigma})$ and the MFCQ is satisfied at this same point. Hence, from Lemma \ref{normal cone estimate}, with the calmness of the set-valued mapping \eqref{PsiCalm}, as corresponding expression of \eqref{CalmnesMapAgain}, it follows that 
\begin{equation} \label{estimate-eq-1}
    N_{\text{gph}S} ( \bar{x}, \bar{y}) \subseteq \bigcup \left \{\partial \langle\lambda, \psi\rangle (\bar{x}, \bar{y}) + N_\Omega (\bar{x}, \bar{y}) \left |\; \lambda \ge 0\right.\right\},
\end{equation}
while considering the fact that $\psi(\bar x, \bar y)=0$, as $\bar y\in S(\bar x)$, and the functions $\tilde{f}$ and $\tilde{g}$ continuously differentiable. Now, considering the definition of the coderivative and inclusion \eqref{estimate-eq-1}, it follows that for all $y^*\in \mathbb{R}^m$, 
\begin{equation} \label{estimate-eq-2}
  D^*S(\bar{x}, \bar{y}) (y^*) \subseteq \{ x^* \in \mathbb{R}^n \left |\; \exists \lambda \ge 0:\quad  \left(x^*, -y^*\right)\in \partial \langle\lambda, \psi\rangle (\bar{x}, \bar{y}) + N_\Omega(\bar{x}, \bar{y}) \right \}.
\end{equation}
Since the MFCQ also holds at $(\bar{x}, \bar{y}, \bar{y})$, using Lemma \ref{normal cone estimate} one more time, 
\begin{equation*}\label{NOmega}
    N_\Omega(\bar{x}, \bar{y}) \subseteq \left\{\nabla g(\bar{x}, \bar{y})^\top v \left|\; v \ge 0,\; g(\bar{x}, \bar{y}) \le 0, \; v^T g(\bar{x}, \bar{y})=0\right.\right\}.
\end{equation*}

On the other hand,  observe that 
\begin{equation*}\label{partialLP}
 \partial \langle\lambda, \psi\rangle (\bar{x}, \bar{y}) \subseteq \lambda \nabla f(\bar{x}, \bar{y}) + \partial \langle \lambda, \, -\varphi\rangle (\bar{x}, \bar{y}) \subseteq \lambda \nabla f(\bar{x}, \bar{y}) -\lambda \bar{\partial} \varphi (\bar{x}, \bar{y})  
\end{equation*}
given that as $\varphi$ is Lipschitz continuous around $(\bar x, \bar y)$, its limiting subdifferential is included in the Clarke subdifferential, according to \eqref{LimitingClarke}. Furthermore, it follows from \cite[Corollary 5.3]{MordukhovichNamPhanVarAnalMargBlP} that the combination of the inner semicontinuity of $S_0$ and MFCQ \eqref{LL regularity} both holding at the point $(\bar x, \bar y, \bar{\varsigma})$ leads to
\begin{equation}\label{SubPhi}
\begin{array}{c}
\bar\partial \varphi(\bar x, \bar y) \;\, \subseteq \;\, \left\{\left.\nabla f_0(\bar x, \bar y)^\top\bar{\varsigma}  +  \nabla_{1, 2} g_0(\bar x, \bar y, \bar{\varsigma})^\top w\right|\;\, w\in \Lambda (\bar x, \bar y, \bar{\varsigma})\right\}.
\end{array}
\end{equation}

Also note that as $\tilde{f}(x, y) = y^T f_0(x, y)$, it holds that
\begin{equation}\label{NablaF}
  \nabla \tilde{f}(x,y)= f_0(x,y) + \nabla f_0(x, y)^\top y.
\end{equation}
Now, let $x^* \in D^*S(\bar{x}, \bar{y})(y^*)$. Then it follows from \eqref{estimate-eq-2}--\eqref{NablaF} that we can find $\lambda$, $v$, $w$ such that 
\[
\begin{array}{r}
\lambda \geq 0,\; v\geq 0, \; g_0(\bar x, \bar y, \bar{y})\leq 0, \; v^\top g_0(\bar x, \bar y, \bar{y})=0,\;  w\in \Lambda(\bar x, \bar y, \bar\varsigma),\\[1.5ex]
\left[\begin{array}{r}
     x^*\\
     -y^*
\end{array}\right]=\left[\begin{array}{r}
 \lambda \left(
  \nabla_1 f_{0}(\bar x, \bar y)^\top  (\bar y- \bar{\varsigma})  - \nabla_1 g_0(\bar x, \bar y, \bar{\varsigma})^\top w\right) + \nabla_1 g_0(\bar x, \bar y, \bar y)^\top v\\[1.5ex]
  \lambda\left.\left(f_0(\bar x, \bar y) + \nabla_2f_0(\bar x, \bar y)^\top (\bar y - \bar\varsigma) - \nabla_2 g_{0}(\bar x, \bar y, \bar\varsigma)^{\top}w  \right)\right. + \nabla_2 g_{0}(\bar x, \bar y, \bar y)^{\top}v
\end{array}\right].
\end{array}
\]
Considering this and the definition of $\Lambda^0 (\bar x, \bar y, \bar{\varsigma}, y^*)$, we have inclusion \eqref{CoD S}.



For assertion (ii), observe that from \eqref{CoD S}, we have the following inclusion:
\[
\begin{array}{ll}
  D^*S(\bar x, \bar y)(0) \subseteq
  & \underset{(v, w, \lambda) \in \Lambda^0 (\bar x, \bar y, \bar\varsigma, 0)}  \bigcup
  \left\{\lambda\left(\nabla_1 f_{0}(\bar x, \bar y)^\top (\bar y - \bar\varsigma) - \nabla_1 g_0(\bar x, \bar y, \bar\varsigma)^\top w\right) + \nabla_1 g_0(\bar x, \bar y, \bar y)^\top v\right\}.
\end{array}
\]
Hence, it is clear that condition \eqref{Stab CQ-1} is sufficient for $D^*S(\bar x, \bar y)(0) \subseteq \{0\}$. Thus, since the coderivative mapping is positively homogeneous (i.e., in particular, we have $0\in D^*S(\bar x, \bar y)(0)$),  the coderivative/Mordukhovich criterion $D^*S(\bar x, \bar y)(0) = \{0\}$ is satisfied. This implies that $S$ is Lipschitz-like around $(\bar x, \bar y)$, and it follows from \eqref{LipModulus} that the exact Lipschitzian bound of $S$ around $(\bar x, \bar y)$ can be obtained as
$$
\text{{lip}}\, S(\bar x, \bar y) = \|D^*S(\bar x, \bar y)\|^+:=\sup\left\{\|u\|\left|\, u\in D^*S(\bar x, \bar y)(y^*), \, \|y^*\|\leq 1\right.\right\}.
$$
Considering inclusion \eqref{CoD S} one more time, we have the stated upper bound on the quantity  $\text{{lip}}\, S(\bar x, \bar y)$. \qed
\end{proof}

